// La regla determinista va ANTES del modelo, no después.
// Todo lo que se puede decidir con una regla escrita no se le pregunta a
// un modelo: es más barato, más rápido y siempre da lo mismo.

const MINIMO_UTIL = 12;      // caracteres con contenido
const MAXIMO = 1200;         // a partir de acá, recortar y avisar

// Un número de pedido es una regla explícita: gana siempre.
const PEDIDO = /(?:pedido|orden|ticket|#)\s*#?\s*(\d{4,8})/i;

function utiles(t) {
  // Saca espacios, emojis y signos: cuenta lo que realmente dice algo.
  return (t || '')
    .replace(/[\p{Extended_Pictographic}\p{Emoji_Presentation}]/gu, '')
    .replace(/[^\p{L}\p{N}]/gu, '')
    .length;
}

const salida = [];

for (const item of $input.all()) {
  const m = item.json;
  const texto = (m.texto || '').trim();

  const pedido = PEDIDO.exec(texto);

  let ruta = 'al_modelo';
  let motivo = null;
  let recortado = false;

  if (utiles(texto) === 0) {
    ruta = 'descartado';
    motivo = 'mensaje_vacio';
  } else if (utiles(texto) < MINIMO_UTIL) {
    ruta = 'descartado';
    motivo = 'demasiado_corto';
  } else if (pedido) {
    // No hace falta interpretar nada: el cliente ya dijo de qué pedido habla.
    ruta = 'soporte';
    motivo = 'trae_numero_de_pedido';
  }

  let textoFinal = texto;
  if (ruta === 'al_modelo' && texto.length > MAXIMO) {
    textoFinal = texto.slice(0, MAXIMO);
    recortado = true;
  }

  salida.push({
    json: {
      ...m,
      texto_para_el_modelo: textoFinal,
      _ruta: ruta,
      _motivo: motivo,
      _pedido: pedido ? pedido[1] : null,
      _recortado: recortado,
      _caracteres: texto.length,
    },
  });
}

return salida;

// El parser garantiza la FORMA. No garantiza el CONTENIDO.
// Un modelo puede devolver un JSON impecable con un puntaje de 840.

const INTENCIONES = ['compra', 'consulta', 'reclamo', 'baja', 'otro'];

const salida = [];

for (const item of $input.all()) {
  const r = item.json.output ?? {};
  const base = $('Guardia deterministica').all()
    .map((i) => i.json)
    .find((m) => m.id === item.json.id) ?? {};

  let motivo = null;

  if (!INTENCIONES.includes(r.intencion)) {
    motivo = 'intencion_fuera_del_enum';
  } else if (typeof r.puntaje !== 'number' || r.puntaje < 0 || r.puntaje > 100) {
    motivo = 'puntaje_fuera_de_rango';
  } else if (typeof r.confianza !== 'number' || r.confianza < 0 || r.confianza > 1) {
    motivo = 'confianza_fuera_de_rango';
  }

  salida.push({
    json: {
      id: item.json.id ?? base.id ?? null,
      texto: base.texto ?? null,
      canal: base.canal ?? null,
      intencion: r.intencion ?? null,
      puntaje: r.puntaje ?? null,
      producto: r.producto ?? null,
      cantidad: r.cantidad ?? null,
      confianza: r.confianza ?? null,
      motivo_modelo: r.motivo ?? null,
      _valido: motivo === null,
      _motivo: motivo,
      _recortado: base._recortado ?? false,
    },
  });
}

return salida;
